  1→import { useState, useCallback, useEffect } from 'react';
  2→import { ThemeProvider } from './contexts/ThemeContext';
  3→import { useTheme } from './hooks/useTheme';
  4→import { useSessionId } from './hooks/useSessionId';
  5→import { LanguageProvider } from './contexts/LanguageContext';
  6→import { useTranslation } from './hooks/useTranslation';
  7→import { AgentProvider } from './contexts/AgentContext';
  8→import { ConfigProvider } from './contexts/ConfigContext';
  9→import { ConversationProvider, useConversation } from './contexts/ConversationContext';
 10→import { FileUpload } from './components/FileUpload';
 11→import { QueryEditor } from './components/QueryEditor';
 12→import { ResultsTable } from './components/ResultsTable';
 13→import { ResultMarkdown } from './components/ResultMarkdown';
 14→import { Sidebar } from './components/Sidebar';
 15→import { ErrorMessage } from './components/ErrorMessage';
 16→import { AgentPanel } from './components/AgentPanel';
 17→import { useAgent } from './hooks/useAgent';
 18→import type { TableInfo, QueryResult } from './types';
 19→import './App.css';
 20→
 21→function findDuplicateFileNames(files: File[]): string[] {
 22→  const seen = new Set<string>();
 23→  const duplicates = new Set<string>();
 24→  for (const file of files) {
 25→    if (seen.has(file.name)) {
 26→      duplicates.add(file.name);
 27→    }
 28→    seen.add(file.name);
 29→  }
 30→  return Array.from(duplicates);
 31→}
 32→
 33→function AppContent({
 34→  tables,
 35→  refreshTables,
 36→  sessionId,
 37→}: {
 38→  tables: TableInfo[];
 39→  refreshTables: () => Promise<void>;
 40→  sessionId: string;
 41→}) {
 42→  const { theme, toggleTheme } = useTheme();
 43→  const { language, setLanguage, t } = useTranslation();
 44→  const [queryResult, setQueryResult] = useState<QueryResult | null>(null);
 45→  const [error, setError] = useState<string | { key: string; params: Record<string, string> } | null>(null);
 46→  const [editorQuery, setEditorQuery] = useState<string | undefined>(
 47→    () => tables.length > 0 ? `SELECT * FROM "${tables[0].name}" LIMIT 100` : undefined
 48→  );
 49→  const [sidebarCollapsed, setSidebarCollapsed] = useState(() => window.innerWidth < 768);
 50→  const [agentOpen, setAgentOpen] = useState(true);
 51→  const [pendingSkillCommand, setPendingSkillCommand] = useState<string | null>(null);
 52→
 53→  const conversation = useConversation();
 54→  const { clearMessages, loadMessages } = useAgent();
 55→
 56→  const handleConversationSelect = useCallback(async (id: string) => {
 57→    const messages = await conversation.selectConversation(id);
 58→    loadMessages(messages);
 59→  }, [conversation, loadMessages]);
 60→
 61→  const handleNewConversation = useCallback(() => {
 62→    conversation.startNewConversation();
 63→    clearMessages();
 64→  }, [conversation, clearMessages]);
 65→
 66→  const handleConversationDelete = useCallback(async (id: string) => {
 67→    await conversation.deleteConversation(id);
 68→    if (conversation.activeConversationId === id) {
 69→      clearMessages();
 70→    }
 71→  }, [conversation, clearMessages]);
 72→
 73→  const handleConversationRename = useCallback(async (id: string, title: string) => {
 74→    await conversation.renameConversation(id, title);
 75→  }, [conversation]);
 76→
 77→  useEffect(() => {
 78→    document.title = t('appTitle');
 79→  }, [t]);
 80→
 81→  useEffect(() => {
 82→    if (tables.length === 0) {
 83→      setQueryResult(null);
 84→      setError(null);
 85→      setEditorQuery(undefined);
 86→    }
 87→  }, [tables]);
 88→
 89→  const errorMessage = error
 90→    ? (typeof error === 'string' ? error : t(error.key, error.params))
 91→    : null;
 92→
 93→  const handleAgentToggle = () => {
 94→    setAgentOpen((prev) => !prev);
 95→  };
 96→
 97→  const handleLoadSample = useCallback(async () => {
 98→    setError(null);
 99→    try {
100→      const response = await fetch('/api/upload/sample', { method: 'POST', headers: { 'X-Session-ID': sessionId } });
101→      if (!response.ok) throw new Error('Failed to load sample dataset');
102→      await refreshTables();
103→      setEditorQuery('SELECT * FROM "titanic" LIMIT 100');
104→    } catch (e) {
105→      setError(e instanceof Error ? e.message : 'Failed to load sample dataset');
106→    }
107→  }, [refreshTables, sessionId]);
108→
109→  const handleFileUpload = useCallback(
110→    async (files: File[]) => {
111→      setError(null);
112→
113→      // Check for duplicate filenames within the batch
114→      const batchDuplicates = findDuplicateFileNames(files);
115→      if (batchDuplicates.length > 0) {
116→        setError({ key: 'duplicateFilesInBatch', params: { names: batchDuplicates.join(', ') } });
117→        return;
118→      }
119→
120→      // Check for filenames that match already-uploaded table names
121→      const existingNames = new Set(tables.map((tbl) => tbl.name));
122→      const alreadyUploaded = files.filter((f) => existingNames.has(f.name)).map((f) => f.name);
123→      if (alreadyUploaded.length > 0) {
124→        setError({ key: 'duplicateFilesExist', params: { names: alreadyUploaded.join(', ') } });
125→        return;
126→      }
127→
128→      let lastName = '';
129→      try {
130→        for (const file of files) {
131→          const formData = new FormData();
132→          formData.append('file', file);
133→          const response = await fetch('/api/upload', {
134→            method: 'POST',
135→            headers: { 'X-Session-ID': sessionId },
136→            body: formData,
137→          });
138→          if (!response.ok) {
139→            const errorData = await response.json();
140→            throw new Error(errorData.detail || 'Failed to upload file');
141→          }
142→          const result = await response.json();
143→          // Handle both single table and array of tables (Excel with multiple sheets)
144→          if (Array.isArray(result)) {
145→            lastName = result[result.length - 1]?.name || '';
146→          } else {
147→            lastName = result.name;
148→          }
149→        }
150→        await refreshTables();
151→        if (lastName) {
152→          setEditorQuery(`SELECT * FROM "${lastName}" LIMIT 100`);
153→        }
154→      } catch (e) {
155→        setError(e instanceof Error ? e.message : 'Failed to upload file');
156→      }
157→    },
158→    [refreshTables, sessionId, tables]
159→  );
160→
161→  const handleQueryExecute = useCallback(
162→    async (sql: string) => {
163→      setError(null);
164→      setQueryResult(null);
165→      try {
166→        const start = performance.now();
167→        const response = await fetch('/api/query', {
168→          method: 'POST',
169→          headers: { 'Content-Type': 'application/json', 'X-Session-ID': sessionId },
170→          body: JSON.stringify({ sql }),
171→        });
172→        const elapsed = performance.now() - start;
173→
174→        if (!response.ok) {
175→          const errorData = await response.json();
176→          throw new Error(errorData.detail || 'Query execution failed');
177→        }
178→
179→        const result = await response.json();
180→        setQueryResult({
181→          columns: result.columns,
182→          rows: result.rows,
183→          rowCount: result.rowCount,
184→          executionTimeMs: elapsed,
185→          resultType: result.resultType,
186→        });
187→        await refreshTables();
188→      } catch (e) {
189→        setError(e instanceof Error ? e.message : 'Query execution failed');
190→      }
191→    },
192→    [refreshTables, sessionId]
193→  );
194→
195→  const handleTableClick = useCallback((tableName: string) => {
196→    setEditorQuery(`SELECT * FROM "${tableName}" LIMIT 100`);
197→  }, []);
