import type { ToolCallResult, UserQuestionData, UserQuestionOption } from '../types';

interface AgentCallbacks {
  onTextChunk: (text: string) => void;
  onThinkingDone: () => void;
  onToolCall: (pending: ToolCallResult) => void;
  onToolResult: (result: ToolCallResult) => void;
  onSubagentStart?: (data: { id: string; name: string; prompt: string }) => void;
  onSubagentEnd?: (data: { id: string; name: string; result?: string; sql_results?: Array<{ sql: string; columns?: string[]; rows?: Record<string, unknown>[]; rowCount?: number; error?: string }>; chart_spec?: { data: unknown[]; layout?: Record<string, unknown> } }) => void;
  onDone: (sessionId: string | null) => void;
  onError: (error: string) => void;
  onUserQuestion?: (data: UserQuestionData) => void;
}

export type { AgentCallbacks };

async function streamSSE(
  response: Response,
  callbacks: AgentCallbacks,
  signal?: AbortSignal,
): Promise<void> {
  const reader = response.body?.getReader();
  if (!reader) {
    callbacks.onError('No response stream');
    return;
  }

  let doneReceived = false;
  const wrappedCallbacks: AgentCallbacks = {
    ...callbacks,
    onDone: (sessionId) => {
      doneReceived = true;
      callbacks.onDone(sessionId);
    },
    onError: (error) => {
      doneReceived = true;
      callbacks.onError(error);
    },
  };

  try {
    const decoder = new TextDecoder();
    let buffer = '';
    let eventType = '';

    while (true) {
      const { done, value } = await reader.read();
      if (done) break;

      buffer += decoder.decode(value, { stream: true });
      const lines = buffer.split('\n');
      buffer = lines.pop() ?? '';
      for (const line of lines) {
        if (line.startsWith('event: ')) {
          eventType = line.slice(7).trim();
        } else if (line.startsWith('data: ')) {
          const data = line.slice(6);
          try {
            const parsed = JSON.parse(data);
            handleSSEEvent(eventType, parsed, wrappedCallbacks);
          } catch {
            // Skip malformed JSON
          }
          eventType = '';
        }
      }
    }

    // Process any remaining data left in buffer after stream ends
    if (buffer.trim()) {
      const remainingLines = buffer.split('\n');
      for (const line of remainingLines) {
        if (line.startsWith('event: ')) {
          eventType = line.slice(7).trim();
        } else if (line.startsWith('data: ')) {
          const data = line.slice(6);
          try {
            const parsed = JSON.parse(data);
            handleSSEEvent(eventType, parsed, wrappedCallbacks);
          } catch {
            // Skip malformed JSON
          }
          eventType = '';
        }
      }
    }

    // Safety net: if stream ended without done/error, force done
    if (!doneReceived) {
      callbacks.onDone(null);
    }
  } catch (e: unknown) {
    if (signal?.aborted) return;
    const msg = e instanceof Error ? e.message : 'Connection failed';
    callbacks.onError(msg);
  }
}

export async function runAgentLoop(
  message: string,
  agentSessionId: string | null,
  langfuseSessionId: string | null,
  conversationHistory: { role: string; content: string }[] | null,
  conversationId?: string | null,
  callbacks?: AgentCallbacks,
  signal?: AbortSignal,
  userSessionId?: string,
  skills?: string[],
): Promise<void> {
  if (!callbacks) return;
  try {
    const response = await fetch('/api/chat', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        ...(userSessionId ? { 'X-Session-ID': userSessionId } : {}),
      },
      body: JSON.stringify({
        message,
        session_id: agentSessionId,
        conversation_id: conversationId,
        langfuse_session_id: langfuseSessionId,
        conversation_history: conversationHistory ?? [],
        ...(skills?.length ? { skills } : {}),
      }),
      signal,
    });

    if (!response.ok) {
      const errorText = await response.text();
      callbacks.onError(`Server error: ${errorText}`);
      return;
    }

    await streamSSE(response, callbacks, signal);
  } catch (e: unknown) {
    if (signal?.aborted) return;
    const msg = e instanceof Error ? e.message : 'Connection failed';
    callbacks.onError(msg);
  }
}

export async function runAgentEditLoop(
  newMessage: string,
  conversationHistory: { role: string; content: string }[],
  langfuseSessionId: string | null,
  callbacks: AgentCallbacks,
  signal?: AbortSignal,
  userSessionId?: string,
): Promise<void> {
  try {
    const response = await fetch('/api/chat/edit', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        ...(userSessionId ? { 'X-Session-ID': userSessionId } : {}),
      },
      body: JSON.stringify({
        new_message: newMessage,
        conversation_history: conversationHistory,
        langfuse_session_id: langfuseSessionId,
      }),
      signal,
    });

    if (!response.ok) {
      const errorText = await response.text();
      callbacks.onError(`Server error: ${errorText}`);
      return;
    }

    await streamSSE(response, callbacks, signal);
  } catch (e: unknown) {
    if (signal?.aborted) return;
    const msg = e instanceof Error ? e.message : 'Connection failed';
    callbacks.onError(msg);
  }
}

function handleSSEEvent(
  eventType: string,
  data: Record<string, unknown>,
  callbacks: AgentCallbacks,
) {
  switch (eventType) {
    case 'thinking':
    case 'answer':
      callbacks.onTextChunk(data.text as string);
      break;
    case 'thinking_done':
      callbacks.onThinkingDone();
      break;
    case 'tool_call':
      callbacks.onToolCall({
        toolCallId: (data.id as string) ?? '',
        toolName: (data.name as string) ?? undefined,
        sql: (data.sql as string) ?? '',
        command: (data.command as string) ?? undefined,
        toolInput: (data.input as Record<string, unknown>) ?? undefined,
        columns: [],
        rows: [],
        rowCount: 0,
      });
      break;
    case 'tool_result': {
      const result: ToolCallResult = {
        toolCallId: (data.id as string) ?? '',
        toolName: (data.name as string) ?? undefined,
        sql: (data.sql as string) ?? '',
        columns: (data.columns as string[]) ?? [],
        rows: (data.rows as Record<string, unknown>[]) ?? [],
        rowCount: (data.rowCount as number) ?? 0,
        error: (data.error as string) ?? undefined,
        output: (data.output as string) ?? undefined,
        rawContent: (data.content as string) ?? undefined,
        chart_spec: (data.chart_spec as { data: unknown[]; layout?: Record<string, unknown> }) ?? undefined,
      };
      callbacks.onToolResult(result);
      break;
    }
    case 'subagent_start':
      callbacks.onSubagentStart?.({
        id: data.id as string,
        name: data.name as string,
        prompt: (data.prompt as string) ?? '',
      });
      break;
    case 'subagent_end': {
      type ChartSpec = { data: unknown[]; layout?: Record<string, unknown>; frames?: unknown[] };
      // Backend sends chart_specs (array) for multi-chart support.
      // Fall back to legacy chart_spec (single object) for backwards compat.
      const rawSpecs = data.chart_specs as ChartSpec[] | undefined;
      const legacySpec = data.chart_spec as ChartSpec | undefined;
      const chartSpecs: ChartSpec[] = rawSpecs ?? (legacySpec ? [legacySpec] : []);

      if (chartSpecs.length > 0) {
        // Emit one callback per chart so each gets its own segment
        for (const spec of chartSpecs) {
          callbacks.onSubagentEnd?.({
            id: data.id as string,
            name: data.name as string,
            chart_spec: spec,
          });
        }
        // Emit text result separately (if any) so it doesn't get lost
        if (data.result) {
          callbacks.onSubagentEnd?.({
            id: data.id as string,
            name: data.name as string,
            result: data.result as string,
          });
        }
      } else {
        callbacks.onSubagentEnd?.({
          id: data.id as string,
          name: data.name as string,
          result: (data.result as string) ?? undefined,
          sql_results: (data.sql_results as Array<{ sql: string; columns?: string[]; rows?: Record<string, unknown>[]; rowCount?: number; error?: string }>) ?? undefined,
        });
      }
      break;
    }
    case 'user_question': {
      // Normalize options: the agent may send plain strings or {label, description} objects
      const rawOptions = (data.options as unknown[]) ?? [];
      const normalizedOptions: UserQuestionOption[] = (Array.isArray(rawOptions) ? rawOptions : []).map(
        (opt: unknown) => {
          if (typeof opt === 'string') return { label: opt };
          if (typeof opt === 'object' && opt !== null && 'label' in opt) return opt as UserQuestionOption;
          return { label: String(opt) };
        }
      );
      callbacks.onUserQuestion?.({
        questionId: data.question_id as string,
        question: data.question as string,
        options: normalizedOptions,
        multiSelect: (data.multi_select as boolean) ?? false,
      });
      break;
    }
    case 'done':
      callbacks.onDone((data.session_id as string) ?? null);
      break;
    case 'error':
      callbacks.onError((data.message as string) ?? 'Unknown error');
      break;
  }
}

                # --- Extract session_id early from system init ---
                elif msg_type == "system":
                    sys_session = msg.get("session_id")
                    if sys_session:
                        actual_session_id = sys_session

    # Persist assistant message if conversation_id provided.
    # Use answer text if available; fall back to all text (covers
    # simple responses where the agent never called tools).
    text_to_persist = assistant_text_parts or all_text_parts
    if conversation_id and text_to_persist:
        try:
            # Finalize segments: flush remaining buffers
            if seg_thinking_buf:
                persisted_segments.append({"type": "thinking", "text": "".join(seg_thinking_buf)})
                seg_thinking_buf.clear()
            # Answer text: use seg_answer_buf (tracks post-thinking text)
            # or assistant_text_parts (tracks post-tool text), or fallback
            answer_text = "".join(seg_answer_buf) if seg_answer_buf else "".join(assistant_text_parts)
            if answer_text:
                persisted_segments.append({"type": "answer", "text": answer_text})
            elif all_text_parts and not persisted_segments:
                # No thinking blocks, no tool calls — all text is the answer
                persisted_segments.append({"type": "answer", "text": "".join(all_text_parts)})

            meta = assistant_metadata.copy() if (assistant_metadata["sql_queries"] or assistant_metadata["chart_specs"]) else {}
            if persisted_segments:
                meta["segments"] = persisted_segments
            memory_store.add_message(
                conversation_id, "assistant", "".join(text_to_persist),
                metadata=meta if meta else None,
            )
        except Exception:
            logger.warning("Failed to persist assistant message", exc_info=True)

    # Guard: always send done even if sidecar ended without result message
    if not done_sent:
        logger.warning("Sidecar stream ended without result message; sending done event")
        yield f"event: error\ndata: {json.dumps({'message': 'Connection to agent was lost. Please try again.'})}\n\n"
        yield f"event: done\ndata: {json.dumps({'session_id': actual_session_id})}\n\n"

except Exception as e:
    logger.error("Container agent error: %s", str(e))
    yield f"event: error\ndata: {json.dumps({'message': str(e)})}\n\n"
# Note: Container is kept alive for session resume (--resume flag) and is
# cleaned up by the background cleanup loop after
# CONTAINER_MAX_LIFETIME_SECONDS, or on application shutdown.
